<?php defined('BASEPATH') or exit('No direct script access allowed'); class Smart_choice_core_enhancements extends AdminController {
 public function calculator(){ $this->load->view('smart_choice_core_enhancements/calculator'); }
 public function contacts(){ $data['q']=trim((string)$this->input->get('q')); $data['contacts']=[]; if($data['q']!==''){ $this->db->select('c.id,c.firstname,c.lastname,c.email,c.phonenumber,c.userid,cl.company'); $this->db->from(db_prefix().'contacts c'); $this->db->join(db_prefix().'clients cl','cl.userid=c.userid','left'); $this->db->group_start()->like('c.firstname',$data['q'])->or_like('c.lastname',$data['q'])->or_like('c.email',$data['q'])->or_like('c.phonenumber',$data['q'])->or_like('cl.company',$data['q'])->group_end(); $data['contacts']=$this->db->limit(100)->get()->result(); } $this->load->view('smart_choice_core_enhancements/contacts',$data); }
 public function reports(){ $this->load->view('smart_choice_core_enhancements/reports'); }
 public function structure_xml(){ if(!is_admin()) access_denied('CRM Structure'); $root=FCPATH; $xml=new SimpleXMLElement('<crm_structure/>'); $xml->addAttribute('generated_at',date('c')); $xml->addAttribute('root',basename(rtrim($root,'/'))); $this->walk($root,$xml,0); $this->output->set_content_type('application/xml')->set_header('Content-Disposition: attachment; filename="crm-structure-'.date('Ymd-His').'.xml"')->set_output($xml->asXML()); }
 private function walk($dir,$node,$depth){ if($depth>6)return; $skip=['.git','node_modules','vendor','uploads','application/cache','application/logs']; foreach(@scandir($dir)?:[] as $name){ if($name==='.'||$name==='..')continue; $path=$dir.DIRECTORY_SEPARATOR.$name; $rel=str_replace(FCPATH,'',$path); foreach($skip as $s){if(strpos($rel,$s)===0)continue 2;} if(is_dir($path)){ $c=$node->addChild('folder');$c->addAttribute('name',$name);$this->walk($path,$c,$depth+1);} else {$c=$node->addChild('file');$c->addAttribute('name',$name);$c->addAttribute('size',(string)@filesize($path));} } }
}
